import{_ as o,C as i,o as t,c as A,a7 as a,b as r,w as E,a as d,E as l,a8 as B}from"./chunks/framework.BCbKzsgW.js";const m=JSON.parse('{"title":"单点登录与企业身份接入","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/sso.md","filePath":"development/common/authentication/sso.md","lastUpdated":1793703140000}'),h={name:"development/common/authentication/sso.md"};function s(u,e,c,p,C,g){const n=i("Mermaid");return t(),A("div",null,[e[1]||(e[1]=a('<h1 id="dan-dian-deng-lu-yu-qi-ye-shen-fen-jie-ru" tabindex="-1">单点登录与企业身份接入 <a class="header-anchor" href="#dan-dian-deng-lu-yu-qi-ye-shen-fen-jie-ru" aria-label="Permalink to &quot;单点登录与企业身份接入&quot;">​</a></h1><p>单点登录（SSO）让多个应用依赖同一个身份提供方完成认证。用户少输入一次密码，只是可见效果；真正需要管理的是中心登录态、各应用本地会话，以及身份与组织成员关系之间的映射。</p><h2 id="zhong-xin-hui-hua-yu-ying-yong-hui-hua" tabindex="-1">中心会话与应用会话 <a class="header-anchor" href="#zhong-xin-hui-hua-yu-ying-yong-hui-hua" aria-label="Permalink to &quot;中心会话与应用会话&quot;">​</a></h2><p>假设应用 A、B 都通过 OIDC 接入身份提供方。图中省略授权码与令牌的详细校验，完整交换见 <a href="./oauth-oidc.html">OIDC 授权码流程</a>；应用 B 的免重复输入，来自中心会话仍有效且认证策略允许。</p>',4)),(t(),r(B,null,{default:E(()=>[l(n,{id:"mermaid-12",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20C%20as%20%E6%B5%8F%E8%A7%88%E5%99%A8%0A%20%20%20%20participant%20A%20as%20%E5%BA%94%E7%94%A8%20A%0A%20%20%20%20participant%20I%20as%20%E7%BB%9F%E4%B8%80%E8%BA%AB%E4%BB%BD%E7%B3%BB%E7%BB%9F%0A%20%20%20%20participant%20B%20as%20%E5%BA%94%E7%94%A8%20B%0A%20%20%20%20C-%3E%3EA%3A%20%E9%A6%96%E6%AC%A1%E8%AE%BF%E9%97%AE%0A%20%20%20%20A--%3E%3EC%3A%20%E9%87%8D%E5%AE%9A%E5%90%91%E5%88%B0%E7%BB%9F%E4%B8%80%E8%BA%AB%E4%BB%BD%E7%B3%BB%E7%BB%9F%0A%20%20%20%20C-%3E%3EI%3A%20%E5%8F%91%E8%B5%B7%20A%20%E7%9A%84%E8%AE%A4%E8%AF%81%E8%AF%B7%E6%B1%82%0A%20%20%20%20I-%3E%3EI%3A%20%E9%AA%8C%E8%AF%81%E7%94%A8%E6%88%B7%3Cbr%3E%E5%BB%BA%E7%AB%8B%E4%B8%AD%E5%BF%83%E4%BC%9A%E8%AF%9D%0A%20%20%20%20I--%3E%3EC%3A%20%E4%B8%AD%E5%BF%83%20Cookie%20%E4%B8%8E%20A%20%E7%9A%84%E5%9B%9E%E8%B0%83%E8%B7%B3%E8%BD%AC%0A%20%20%20%20C-%3E%3EA%3A%20%E6%90%BA%E5%B8%A6%20A%20%E7%9A%84%E6%8E%88%E6%9D%83%E7%A0%81%E5%9B%9E%E8%B0%83%0A%20%20%20%20A-%3E%3EI%3A%20%E5%85%91%E6%8D%A2%E6%8E%88%E6%9D%83%E7%A0%81%E5%B9%B6%E5%8F%96%E5%BE%97%E4%BB%A4%E7%89%8C%0A%20%20%20%20I--%3E%3EA%3A%20A%20%E5%AF%B9%E5%BA%94%E7%9A%84%E8%AE%A4%E8%AF%81%E7%BB%93%E6%9E%9C%0A%20%20%20%20A--%3E%3EC%3A%20%E5%BB%BA%E7%AB%8B%20A%20%E7%9A%84%E6%9C%AC%E5%9C%B0%E4%BC%9A%E8%AF%9D%0A%20%20%20%20C-%3E%3EB%3A%20%E9%9A%8F%E5%90%8E%E8%AE%BF%E9%97%AE%20B%0A%20%20%20%20B--%3E%3EC%3A%20%E5%8F%91%E8%B5%B7%20B%20%E7%9A%84%E7%8B%AC%E7%AB%8B%E8%AE%A4%E8%AF%81%E8%B7%B3%E8%BD%AC%0A%20%20%20%20C-%3E%3EI%3A%20B%20%E7%9A%84%E8%AE%A4%E8%AF%81%E8%AF%B7%E6%B1%82%E4%B8%8E%E4%B8%AD%E5%BF%83%20Cookie%0A%20%20%20%20I-%3E%3EI%3A%20%E4%B8%AD%E5%BF%83%E4%BC%9A%E8%AF%9D%E6%9C%89%E6%95%88%3Cbr%3E%E7%AD%96%E7%95%A5%E5%85%81%E8%AE%B8%E5%85%8D%E8%BE%93%E5%85%A5%0A%20%20%20%20I--%3E%3EC%3A%20%E9%87%8D%E5%AE%9A%E5%90%91%E5%88%B0%20B%20%E7%9A%84%E5%9B%9E%E8%B0%83%0A%20%20%20%20C-%3E%3EB%3A%20%E6%90%BA%E5%B8%A6%20B%20%E7%9A%84%E6%8E%88%E6%9D%83%E7%A0%81%E5%9B%9E%E8%B0%83%0A%20%20%20%20B-%3E%3EI%3A%20%E5%85%91%E6%8D%A2%E6%8E%88%E6%9D%83%E7%A0%81%E5%B9%B6%E5%8F%96%E5%BE%97%E4%BB%A4%E7%89%8C%0A%20%20%20%20I--%3E%3EB%3A%20B%20%E5%AF%B9%E5%BA%94%E7%9A%84%E8%AE%A4%E8%AF%81%E7%BB%93%E6%9E%9C%0A%20%20%20%20B--%3E%3EC%3A%20%E5%BB%BA%E7%AB%8B%20B%20%E7%9A%84%E6%9C%AC%E5%9C%B0%E4%BC%9A%E8%AF%9D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>两次回调分别关联各自发起的登录事务。身份系统的 Cookie 只在访问其域名时发送，不交给 A 或 B；两个应用也不会互相收到对方的本地会话 Cookie。</p><p>A、B 可以位于不同域名，不必共享 Cookie。每个应用仍有独立 <code>client_id</code>、回调、受众与权限边界；SSO 不是把 A 的会话字符串直接复制给 B。</p><p>共享父域 Cookie 虽然容易起步，却会扩大子域被攻破后的影响，也无法自然支持不同主域。若选择这种架构，应把所有可接触 Cookie 的应用都视作同一信任边界，而不是声称各子应用完全隔离。</p><h2 id="san-zhong-tui-chu-yu-yi" tabindex="-1">三种退出语义 <a class="header-anchor" href="#san-zhong-tui-chu-yu-yi" aria-label="Permalink to &quot;三种退出语义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>涉及状态</th><th>用户可能观察到的结果</th></tr></thead><tbody><tr><td>应用本地退出</td><td>A 的本地 Session</td><td>B 仍在线；再次进入 A 可能通过中心会话自动登录</td></tr><tr><td>中心退出</td><td>身份提供方会话</td><td>不一定已经清除 A、B 本地 Session</td></tr><tr><td>联动退出</td><td>中心与相关应用会话</td><td>受协议支持、投递成功和本地处理影响</td></tr></tbody></table><p>产品文案要对应实际语义。“退出此应用”和“退出所有应用”不能共用一个只删除本地 Cookie 的实现。</p><p><a href="https://openid.net/specs/openid-connect-rpinitiated-1_0.html" target="_blank" rel="noreferrer">OIDC RP-Initiated Logout</a>定义应用请求身份提供方退出的机制。应用仍需清理自己的会话，退出后的跳转地址也需要按提供方注册与校验规则处理，不能任意接受外部 URL。</p><h2 id="lian-dong-tui-chu-yu-tou-di-shi-bai" tabindex="-1">联动退出与投递失败 <a class="header-anchor" href="#lian-dong-tui-chu-yu-tou-di-shi-bai" aria-label="Permalink to &quot;联动退出与投递失败&quot;">​</a></h2><p><a href="https://openid.net/specs/openid-connect-backchannel-1_0.html" target="_blank" rel="noreferrer">OIDC Back-Channel Logout</a>通过服务端直接投递 Logout Token，减少对浏览器页面与第三方 Cookie 的依赖。RP 验证签名、issuer、audience、时间、事件类型及主体或会话标识，再撤销对应本地会话。</p><p>实现还要保留 <code>(issuer, sid)</code> 或适当的主体到本地会话映射，不能把 Logout Token 当作普通登录令牌接受。重复通知按幂等方式成功处理；已退出的目标会话无需再次报错。</p><p>服务端通知仍可能超时。设计需要明确：</p><ul><li>投递失败是否重试，积压是否告警。</li><li>多实例的会话缓存如何失效。</li><li>未接入退出协议的应用，最晚何时重新检查中心或本地账号状态。</li><li>退出后已经签发的 Access Token 如何处理。</li></ul><p>“支持统一退出”不代表零延迟撤销。应给出经过验证的最坏生效时间，并区分中心会话、本地会话和 API 令牌。</p><h2 id="qi-ye-shen-fen-yu-ben-di-zhang-hao" tabindex="-1">企业身份与本地账号 <a class="header-anchor" href="#qi-ye-shen-fen-yu-ben-di-zhang-hao" aria-label="Permalink to &quot;企业身份与本地账号&quot;">​</a></h2><p>同一员工可能在不同企业拥有不同身份。企业接入需要把连接配置与租户绑定，明确允许哪些 issuer、客户端、域名与成员来源。</p><p>仅看到邮箱后缀是 <code>company.example</code>，不足以认定其拥有企业管理员权限。企业连接开通应由有权管理员完成验证，成员登录后还要核对该连接对应的租户与成员状态。</p><p>外部组到本地角色的映射使用允许列表，并区分租户角色与平台管理员。未知组、缺失字段、超长组列表或大小写差异都不能默认提升权限。组或角色变更还需要定义已签发令牌的滞后窗口。</p><h2 id="shou-ci-deng-lu-kai-tong-yu-mu-lu-tong-bu" tabindex="-1">首次登录开通与目录同步 <a class="header-anchor" href="#shou-ci-deng-lu-kai-tong-yu-mu-lu-tong-bu" aria-label="Permalink to &quot;首次登录开通与目录同步&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>开通时机</th><th>适用约束</th></tr></thead><tbody><tr><td>管理员邀请</td><td>登录之前</td><td>审批明确，维护成本较高</td></tr><tr><td>JIT 开通</td><td>首次成功登录时</td><td>依赖企业连接和映射策略，需处理并发与席位限制</td></tr><tr><td>目录同步</td><td>外部目录推送或同步时</td><td>可提前开通、禁用和调整组关系</td></tr></tbody></table><p>JIT（Just-in-Time）只在用户登录时发生，无法单独保证离职员工及时停权。SCIM 提供跨域身份管理协议，见 <a href="https://www.rfc-editor.org/rfc/rfc7644.html" target="_blank" rel="noreferrer">RFC 7644</a>；它承担账号或组的管理，与 OIDC 登录互补，不能互相替代。</p><p>目录同步事件要校验来源、租户和外部对象 ID，并处理幂等、乱序与部分失败。旧的“激活用户”事件晚于禁用事件到达时，不应自动恢复访问。可以维护来源版本、更新时间约束和定期对账。</p><h2 id="chi-zhi-ting-quan" tabindex="-1">离职停权 <a class="header-anchor" href="#chi-zhi-ting-quan" aria-label="Permalink to &quot;离职停权&quot;">​</a></h2><p>一次完整的停权至少要核查以下对象：</p><ol><li>租户成员状态与角色。</li><li>当前应用会话及关联刷新族。</li><li>个人 Access Token、API Key 和代表用户运行的集成。</li><li>后台任务、导出、共享链接与资源所有权。</li><li>上游目录与本地状态之间的同步积压。</li></ol><p>禁用租户成员不必注销个人账号，但与该企业相关的调用必须停止。离职人员创建的业务数据通常需要移交；具体归属与保留规则属于业务决策。</p><h2 id="shen-fen-ti-gong-fang-bu-ke-yong" tabindex="-1">身份提供方不可用 <a class="header-anchor" href="#shen-fen-ti-gong-fang-bu-ke-yong" aria-label="Permalink to &quot;身份提供方不可用&quot;">​</a></h2><p>中心不可用时，新登录和需要重新认证的操作通常失败；已建立本地 Session 是否继续有效，取决于本地期限与风险策略。应避免把每个低风险请求都变成对身份提供方的同步依赖，同时也不能无期限接受旧成员状态。</p><p>紧急管理员账号需要独立流程：限制使用范围、强认证、必要告警与事后复核。它是经过治理的恢复入口，不应成为所有员工都可使用的密码登录后门。</p><p>企业已有 SAML 时，应使用成熟实现核对元数据、签名、受众、时间与请求关联；不要为了统一技术栈自行解析和验证 XML 签名。本专题的流程示例以 OIDC 为主。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>OpenID Foundation：<a href="https://openid.net/specs/openid-connect-rpinitiated-1_0.html" target="_blank" rel="noreferrer">RP-Initiated Logout 1.0</a></li><li>OpenID Foundation：<a href="https://openid.net/specs/openid-connect-backchannel-1_0.html" target="_blank" rel="noreferrer">Back-Channel Logout 1.0</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc7644.html" target="_blank" rel="noreferrer">RFC 7644 — SCIM Protocol</a></li></ul><h3 id="gong-cheng-shi-jian-yu-she-qu-wen-zhang" tabindex="-1">工程实践与社区文章 <a class="header-anchor" href="#gong-cheng-shi-jian-yu-she-qu-wen-zhang" aria-label="Permalink to &quot;工程实践与社区文章&quot;">​</a></h3><ul><li>程晓飞（火山引擎开发者社区转载）：<a href="https://developer.volcengine.com/articles/7383052848092839946" target="_blank" rel="noreferrer">用Python建设企业认证和权限控制平台</a>——Django、LDAP、CAS 与企业统一用户平台的建设案例。</li></ul>',33))])}const f=o(h,[["render",s]]);export{m as __pageData,f as default};
